import numpy as np, cv2

def compute_psnr(ref, test):
    mse = np.mean((ref.astype(np.float64) - test.astype(np.float64)) ** 2)
    return 100.0 if mse == 0 else float(10.0 * np.log10((255.0 ** 2) / mse))

def eval_denoising():
    np.random.seed(42)
    clean = np.full((128, 128), 50, dtype=np.uint8)
    clean[32:96, 32:96] = 210
    noisy = np.clip(clean + np.random.normal(0, 25, clean.shape), 0, 255).astype(np.uint8)
    res_mean = cv2.blur(noisy, (5, 5))
    res_bilat = cv2.bilateralFilter(noisy, 7, 50, 50)
    return compute_psnr(clean, noisy), compute_psnr(clean, res_mean), compute_psnr(clean, res_bilat)
